DO $$ DECLARE
  sid UUID := '00000000-0000-0000-0000-000000000001';
  kan_id UUID := '4c526c8b-60b4-464f-af4f-85611b50aaf5';
  c10_id UUID := 'aca6ed6e-2263-4841-be61-10db6a280f21';
BEGIN
  DELETE FROM quiz_responses WHERE question_id IN (SELECT id FROM questions WHERE subject_id=kan_id);
  DELETE FROM quiz_questions WHERE question_id IN (SELECT id FROM questions WHERE subject_id=kan_id);
  DELETE FROM questions WHERE subject_id=kan_id AND deleted_at IS NULL;
END $$;
